const lessons=[{"sentences":[{"speaker":"A","text":"We need to prepare our questions for the upcoming college interview project.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.657041666666666},{"speaker":"B","text":"I already drafted five open questions about local business management.","position":2,"audioStartSeconds":4.8570416666666665,"audioEndSeconds":9.705875},{"speaker":"A","text":"Those sound great although we should probably add something about digital marketing too.","position":3,"audioStartSeconds":9.905875,"audioEndSeconds":15.074208333333333},{"speaker":"B","text":"That is a smart idea because every company uses social media nowadays.","position":4,"audioStartSeconds":15.274208333333334,"audioEndSeconds":20.28783333333333},{"speaker":"A","text":"Should we also ask about their future expansion plans if time permits?","position":5,"audioStartSeconds":20.487833333333334,"audioEndSeconds":25.101208333333332},{"speaker":"B","text":"Only if the manager finishes answering the core questions quickly enough.","position":6,"audioStartSeconds":25.301208333333335,"audioEndSeconds":29.824416666666668},{"speaker":"A","text":"Who should we contact first to schedule this recorded interview?","position":7,"audioStartSeconds":30.024416666666667,"audioEndSeconds":34.01929166666667},{"speaker":"B","text":"My uncle runs a small bookstore downtown so he might agree to help us.","position":8,"audioStartSeconds":34.21929166666666,"audioEndSeconds":39.257958333333335},{"speaker":"A","text":"That location is convenient when we want to carry our heavy recording equipment.","position":9,"audioStartSeconds":39.45795833333333,"audioEndSeconds":44.522375},{"speaker":"B","text":"Let us call him tomorrow morning before someone else books his schedule.","position":10,"audioStartSeconds":44.722375,"audioEndSeconds":49.206916666666665},{"speaker":"A","text":"Do we need to bring extra microphones or will your smartphone recorder suffice?","position":11,"audioStartSeconds":49.40691666666667,"audioEndSeconds":54.34170833333334},{"speaker":"B","text":"We definitely need the external microphone because ambient noise can ruin the audio.","position":12,"audioStartSeconds":54.54170833333333,"audioEndSeconds":59.94116666666667},{"speaker":"A","text":"I will charge both batteries tonight so we avoid any technical failures.","position":13,"audioStartSeconds":60.14116666666666,"audioEndSeconds":64.922875},{"speaker":"B","text":"Perfect and I will print out the consent forms for him to sign.","position":14,"audioStartSeconds":65.122875,"audioEndSeconds":69.28525},{"speaker":"A","text":"Everything is organized now so we can definitely finish this assignment successfully.","position":15,"audioStartSeconds":69.48525,"audioEndSeconds":74.68775},{"speaker":"B","text":"I agree completely with your plan so let us meet outside the library tomorrow.","position":16,"audioStartSeconds":74.88775,"audioEndSeconds":79.85908333333333}],"questions":[{"prompt":"What topic do the speakers decide to add to their interview questions?","options":["Digital marketing.","Financial accounting.","Staff recruitment."],"answer":"A","evidenceSentence":3,"evidence":"add something about digital marketing","explanation":"Speaker A đề xuất thêm câu hỏi về tiếp thị kỹ thuật số và Speaker B đồng ý."},{"prompt":"Why do they initially reject asking about expansion plans?","options":["The manager will not know the answer.","There might not be enough time.","It is too complicated for a college project."],"answer":"B","evidenceSentence":6,"evidence":"if the manager finishes answering the core questions quickly enough","explanation":"Họ chỉ hỏi về kế hoạch mở rộng nếu thời gian cho phép khi người quản lý trả lời xong các câu hỏi chính."},{"prompt":"Who is suggested as the first person to interview?","options":["A local cafe owner.","A bookstore manager.","A university professor."],"answer":"B","evidenceSentence":8,"evidence":"My uncle runs a small bookstore","explanation":"Speaker B đề xuất người chú đang quản lý một hiệu sách nhỏ ở trung tâm."},{"prompt":"What equipment problem are they trying to prevent?","options":["Poor audio quality from background noise.","Running out of phone storage space.","Breaking the camera lens during transport."],"answer":"A","evidenceSentence":12,"evidence":"ambient noise can ruin the audio","explanation":"Họ dùng micro ngoài vì tiếng ồn xung quanh có thể làm hỏng bản ghi âm."},{"prompt":"What task does Speaker A agree to do tonight?","options":["Print the consent forms.","Call the bookstore owner.","Charge the batteries."],"answer":"C","evidenceSentence":13,"evidence":"I will charge both batteries tonight","explanation":"Speaker A nhận nhiệm vụ sạc đầy pin cho thiết bị vào tối nay."},{"prompt":"What is the final agreement regarding where they will meet tomorrow?","options":["Outside the library.","Inside the bookstore.","At the campus cafe."],"answer":"A","evidenceSentence":16,"evidence":"meet outside the library tomorrow","explanation":"Cuối cùng hai người thống nhất gặp nhau ở bên ngoài thư viện vào ngày mai."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
